mapper.select:
SELECT
    COALESCE(SUM(CASE
        WHEN status = 'SUCCESS'
         AND paid_at >= #{rangeStart}
         AND paid_at < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS successCount,
    COALESCE(SUM(CASE
        WHEN status = 'SUCCESS'
         AND paid_at >= #{rangeStart}
         AND paid_at < #{rangeEnd}
        THEN COALESCE(paid_amount, amount) ELSE 0 END), 0) AS successAmount,
    COALESCE(SUM(CASE
        WHEN status = 'SUCCESS'
         AND paid_at >= #{rangeStart}
         AND paid_at < #{rangeEnd}
        THEN merchant_fee_amount ELSE 0 END), 0) AS feeAmount,
    COALESCE(SUM(CASE
        WHEN status = 'FAILED'
         AND failed_at >= #{rangeStart}
         AND failed_at < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS failedCount,
    COALESCE(SUM(CASE
        WHEN status = 'CLOSED'
         AND closed_at >= #{rangeStart}
         AND closed_at < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS closedCount,
    COALESCE(SUM(CASE
        WHEN status IN ('CREATED', 'PROCESSING')
        THEN 1 ELSE 0 END), 0) AS processingCount
FROM pay_order
WHERE tenant_id = #{tenantId}
  AND currency = #{currency}

SELECT
    COALESCE(SUM(CASE
        WHEN status = 'SUCCESS'
         AND COALESCE(completed_at, updated_at) >= #{rangeStart}
         AND COALESCE(completed_at, updated_at) < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS successCount,
    COALESCE(SUM(CASE
        WHEN status = 'SUCCESS'
         AND COALESCE(completed_at, updated_at) >= #{rangeStart}
         AND COALESCE(completed_at, updated_at) < #{rangeEnd}
        THEN amount ELSE 0 END), 0) AS successAmount,
    COALESCE(SUM(CASE
        WHEN status = 'SUCCESS'
         AND COALESCE(completed_at, updated_at) >= #{rangeStart}
         AND COALESCE(completed_at, updated_at) < #{rangeEnd}
        THEN merchant_fee_amount ELSE 0 END), 0) AS feeAmount,
    COALESCE(SUM(CASE
        WHEN status = 'FAILED'
         AND failed_at >= #{rangeStart}
         AND failed_at < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS failedCount,
    COALESCE(SUM(CASE
        WHEN status IN ('CREATED', 'FROZEN', 'PROCESSING')
        THEN 1 ELSE 0 END), 0) AS processingCount
FROM payout_order
WHERE tenant_id = #{tenantId}
  AND currency = #{currency}

SELECT COUNT(DISTINCT merchant_id)
FROM (
    SELECT merchant_id
    FROM pay_order
    WHERE tenant_id = #{tenantId}
      AND currency = #{currency}
      AND status = 'SUCCESS'
      AND paid_at >= #{rangeStart}
      AND paid_at < #{rangeEnd}
    UNION
    SELECT merchant_id
    FROM payout_order
    WHERE tenant_id = #{tenantId}
      AND currency = #{currency}
      AND status = 'SUCCESS'
      AND COALESCE(completed_at, updated_at) >= #{rangeStart}
      AND COALESCE(completed_at, updated_at) < #{rangeEnd}
) active_merchants

SELECT
    (
        SELECT COUNT(1)
        FROM pay_order
        WHERE tenant_id = #{tenantId}
          AND currency = #{currency}
          AND status = 'MANUAL_REVIEW'
    ) + (
        SELECT COUNT(1)
        FROM payout_order
        WHERE tenant_id = #{tenantId}
          AND currency = #{currency}
          AND status = 'MANUAL_REVIEW'
    ) AS manualReview,
    (
        SELECT COUNT(1)
        FROM pay_order
        WHERE tenant_id = #{tenantId}
          AND currency = #{currency}
          AND merchant_notify_status = 'FAILED'
    ) + (
        SELECT COUNT(1)
        FROM payout_order
        WHERE tenant_id = #{tenantId}
          AND currency = #{currency}
          AND merchant_notify_status = 'FAILED'
    ) AS notifyFailed,
    (
        SELECT COUNT(1)
        FROM pay_order
        WHERE tenant_id = #{tenantId}
          AND currency = #{currency}
          AND status = 'SUCCESS'
          AND settle_status = 'PENDING'
          AND settle_release_at IS NOT NULL
          AND settle_release_at <= UTC_TIMESTAMP(3)
    ) AS settleDue,
    (
        SELECT COUNT(1)
        FROM pay_order
        WHERE tenant_id = #{tenantId}
          AND currency = #{currency}
          AND status IN ('CREATED', 'PROCESSING')
    ) AS processingPay,
    (
        SELECT COUNT(1)
        FROM payout_order
        WHERE tenant_id = #{tenantId}
          AND currency = #{currency}
          AND status IN ('CREATED', 'FROZEN', 'PROCESSING')
    ) AS processingPayout
